def get_entry(key: str) -> dict:
    try:
        return ENTRIES[key]
    except KeyError:
        raise ValueError(f"embedded exact-LZ key not found: {key}")


def read_indexed_png(path: Path):
    with Image.open(path) as img:
        if img.mode != "P":
            raise ValueError(f"{path}: indexed PNG (mode P) required, got {img.mode}")
        w, h = img.size
        if w % 8 or h % 8:
            raise ValueError(f"{path}: dimensions must be multiples of 8: {w}x{h}")
        pixels = list(img.getdata())
    return w, h, pixels


def indexed_png_to_tiled(path: Path, bpp: int) -> bytes:
    w, h, pixels = read_indexed_png(path)
    limit = 16 if bpp == 4 else 256
    if pixels and max(pixels) >= limit:
        raise ValueError(f"{path}: palette index exceeds {limit - 1}")

    out = bytearray()
    for ty in range(0, h, 8):
        for tx in range(0, w, 8):
            if bpp == 4:
                for y in range(8):
                    row = (ty + y) * w + tx
                    for x in range(0, 8, 2):
                        out.append(pixels[row + x] | (pixels[row + x + 1] << 4))
            else:
                for y in range(8):
                    row = (ty + y) * w + tx
                    out.extend(pixels[row:row + 8])
    return bytes(out)


def parse_inc_bytes(path: Path) -> bytes:
    out = bytearray()
    for lineno, source in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        line = source.split("@", 1)[0].strip()
        if not line:
            continue
        m = re.fullmatch(r"\.byte\s+(.+)", line)
        if not m:
            raise ValueError(f"{path}:{lineno}: only .byte directives are allowed")
        for field in m.group(1).split(','):
            value = int(field.strip(), 0)
            if not 0 <= value <= 0xFF:
                raise ValueError(f"{path}:{lineno}: byte out of range: {field}")
            out.append(value)
    return bytes(out)


def cmd_repack_png(args):
    entry = get_entry(args.key)
    bpp = int(entry["bpp"])
    raw = indexed_png_to_tiled(Path(args.input), bpp)
    expected = int(entry["raw_size"])
    if len(raw) != expected:
        raise ValueError(f"{args.input}: raw size 0x{len(raw):X}, expected 0x{expected:X}")
    encoded = repack_raw_with_plan(raw, entry["plan"])
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(encoded)


def cmd_repack_inc(args):
    entry = get_entry(args.key)
    raw = parse_inc_bytes(Path(args.input))
    expected = int(entry["raw_size"])
    if len(raw) != expected:
        raise ValueError(f"{args.input}: raw size 0x{len(raw):X}, expected 0x{expected:X}")
    encoded = repack_raw_with_plan(raw, entry["plan"])
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(encoded)


def cmd_encode_palette(args):
    path = Path(args.input)
    with Image.open(path) as img:
        image = img.convert("RGB")
    if image.width % 16:
        raise ValueError(f"{path}: palette PNG width must be divisible by 16")
    cell = image.width // 16
    if cell <= 0 or image.height % cell:
        raise ValueError(f"{path}: invalid palette cell geometry")
    rows = image.height // cell
    output = bytearray()
    for index in range(rows * 16):
        x = (index % 16) * cell + cell // 2
        y = (index // 16) * cell + cell // 2
        r, g, b = image.getpixel((x, y))
        value = (r >> 3) | ((g >> 3) << 5) | ((b >> 3) << 10)
        output.extend(value.to_bytes(2, "little"))
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(output)


def main() -> int:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("repack-png")
    p.add_argument("--key", required=True)
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_repack_png)

    p = sub.add_parser("repack-inc")
    p.add_argument("--key", required=True)
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_repack_inc)

    p = sub.add_parser("encode-palette")
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_encode_palette)

    args = ap.parse_args()
    try:
        args.func(args)
    except (OSError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
